values
  ('6751200e-7f2f-46ea-b476-570277970ca6', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', null, 'topic'::public.curated_course_node_type, 'Area Studies, Anthropology, and the Problem of Region', 'Students begin by asking what a region is, who defines it, and how ethnography can study place without freezing cultures into bounded containers.', 0),
  ('02bc25ed-d4d0-42ce-890c-569ff2b54209', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', '6751200e-7f2f-46ea-b476-570277970ca6', 'subtopic'::public.curated_course_node_type, 'What counts as a region', 'This subtopic introduces region as an analytic, historical, political, and lived category rather than a neutral map label.', 0),
  ('b42d3c46-1c46-42e0-af9f-e4d10ed6ef5f', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', '02bc25ed-d4d0-42ce-890c-569ff2b54209', 'concept'::public.curated_course_node_type, 'Culture areas, nation-states, borderlands, oceans, diasporas, and transregional circuits', null, 0),
