  ('ccad6cfc-84f1-40ad-9fcb-39b04e040ed9', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', 'e3c0fcdc-b632-4da3-9d9c-69b15bb2845c', 'concept'::public.curated_course_node_type, 'Ethnography, participant observation, and local categories of meaning', null, 0),
