  ('e41b9b54-bb47-4641-b1d3-8610522fd5c6', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', 'a9084f21-79c2-49f9-819e-92ea67acb1bd', 'concept'::public.curated_course_node_type, 'Orientalism, colonial knowledge, extraction, and representation', null, 1),
  ('4049724c-7cdc-47f4-9a6b-a31a2cc5eaec', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', 'a9084f21-79c2-49f9-819e-92ea67acb1bd', 'concept'::public.curated_course_node_type, 'Ethical humility, uncertainty, and responsible claims about place', null, 2),
