  ('20c0df8c-44ee-48ed-b5b0-dfe8cdd860ab', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', '30f94f8c-579b-420e-b6b6-407133eadfd9', 'subtopic'::public.curated_course_node_type, 'Historical foundations', 'Area studies requires students to see the present as historically produced, not as timeless culture.', 0),
