  ('a95caf4f-148a-4e87-ad08-027fd63b3691', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', '20c0df8c-44ee-48ed-b5b0-dfe8cdd860ab', 'concept'::public.curated_course_node_type, 'Colonial rule, border making, labor regimes, and missionization', null, 1),
  ('dad0d38c-f5fa-4714-aecf-1044800424c4', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', '20c0df8c-44ee-48ed-b5b0-dfe8cdd860ab', 'concept'::public.curated_course_node_type, 'Independence, revolution, development projects, and contemporary transformations', null, 2),
  ('ee0e0e37-390b-416b-8808-868e67a3eefd', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', '30f94f8c-579b-420e-b6b6-407133eadfd9', 'subtopic'::public.curated_course_node_type, 'Key anthropological debates by region', 'Students learn to identify the arguments that have shaped scholarship in the region they choose.', 1),
  ('34a69251-a95f-41eb-9a4c-69d31e4b523b', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', 'ee0e0e37-390b-416b-8808-868e67a3eefd', 'concept'::public.curated_course_node_type, 'Classic ethnographies, revisionist scholarship, and contemporary field debates', null, 0),
