  ('1a946926-77a9-467b-bec9-6581290bbb37', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', '1b5837e0-3f98-4fa4-9643-646e8e5a8c4e', 'concept'::public.curated_course_node_type, 'Scholarly monographs, articles, archives, oral histories, and primary sources', null, 0),
  ('cde11604-4afd-449a-ae74-d628410015a9', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', '1b5837e0-3f98-4fa4-9643-646e8e5a8c4e', 'concept'::public.curated_course_node_type, 'News, government documents, NGO reports, cultural production, and social media', null, 1),
  ('1dc8840a-e9f0-40aa-bc7b-8f5023686ed6', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', '1b5837e0-3f98-4fa4-9643-646e8e5a8c4e', 'concept'::public.curated_course_node_type, 'Evaluating disciplinary assumptions and evidentiary standards', null, 2),
