  ('995c0412-26e7-407d-89a9-4a9b7087a40a', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', '5f8cb2bb-d95e-40d8-a21f-3ba8f9af9af5', 'subtopic'::public.curated_course_node_type, 'Fieldsite selection and research design', 'This subtopic turns regional curiosity into a workable research question and evidence plan.', 0),
