  ('41470754-f131-4cc9-a598-922f3e68a195', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', '995c0412-26e7-407d-89a9-4a9b7087a40a', 'concept'::public.curated_course_node_type, 'Sampling, interlocutor diversity, triangulation, and scope control', null, 2),
