  ('eea60f59-3161-46e2-be60-a8c4705c71ca', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', '758cf3de-003e-410e-9cdc-04751f011dd6', 'concept'::public.curated_course_node_type, 'Recording, transcription, translation, confidentiality, and follow-up', null, 2),
