  ('52629c54-516a-41cf-a6b7-accf9f55effe', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', 'c74e4abe-62cd-492f-9dae-d73723026dec', 'concept'::public.curated_course_node_type, 'Jottings, expanded fieldnotes, analytic memos, and reflexive notes', null, 0),
  ('5e2642da-9a44-42b2-96be-a2367ab7eb1d', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', 'c74e4abe-62cd-492f-9dae-d73723026dec', 'concept'::public.curated_course_node_type, 'Coding, thematic analysis, narrative analysis, and negative cases', null, 1),
  ('6f581035-2d08-43fc-a959-39ceaf288f4c', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', 'c74e4abe-62cd-492f-9dae-d73723026dec', 'concept'::public.curated_course_node_type, 'Building claims from evidence while preserving ambiguity and context', null, 2),
  ('41c9782d-2554-4379-9ddf-1ed272a0c36d', 'a5b6c7d8-9e0f-4b15-8c45-5d6e7f8a9b55', null, 'topic'::public.curated_course_node_type, 'Colonialism, Postcoloniality, and Global Power', 'Students analyze how colonial rule, empire, capitalism, and global hierarchy continue to shape regional identities, institutions, and inequalities.', 3);
